{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We used meta-analysis to evaluate the pooled rate of SARS-CoV-2 reinfection in the included studies... Therefore, we converted the reinfection rate to an approximate normal distribution. Four transformations were taken: log transformation, logit transformation, arcsine transformation, and double arcsine transformation. Through the hypothesis test after the transformation, we decided to use the logit transformation",
      "reason": "The effect measure for the single outcome (reinfection rate, presented as proportions with 95% CIs) is specified, including the logit transformation of rates used in synthesis."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No thresholds or ranges for interpreting effect size magnitude (e.g., clinically important thresholds) are reported anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The synthesized outcome is a rate/proportion presented as such; no re-expression of results into another effect measure was performed or needed, and no evidence of re-expression methods exists."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "However, when the rate is close to 0 or 1, two problems will occur in the meta-regression: the confidence interval may exceed the interval of 0-1, and the variance is squeezed towards 0. Therefore, we converted the reinfection rate to an approximate normal distribution... we decided to use the logit transformation",
      "reason": "The choice of the logit transformation is justified by statistical problems with rates near 0 or 1, but the choice of rate/proportion as the effect measure itself is not explicitly justified."
    }
  ],
  "confidence": 85
}

